  17| 
  18| export function paginate<T extends { id: string }>(
  19|   items: readonly T[],
  20|   query: { cursor?: string | undefined; limit: number },
  21| ): { data: T[]; nextCursor: string | null } {
  22|   let start = 0;
  23|   if (query.cursor !== undefined) {
  24|     const afterId = decodeCursor(query.cursor);
  25|     const index = items.findIndex((i) => i.id === afterId);
  26|     if (index === -1) throw new HttpProblem(422, "Invalid cursor", "cursor does not match any item", "validation");
  27|     start = index + 1;
  28|   }
  29|   const data = items.slice(start, start + query.limit);
  30|   const last = data[data.length - 1];
  31|   const nextCursor = last !== undefined && start + query.limit < items.length ? encodeCursor(last.id) : null;
  32|   return { data, nextCursor };
